<?php
declare(strict_types=1);
ob_start(); session_start(); require dirname(__DIR__,2).'/config/config.php';
function fs_json(int $status,array $body):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($body,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
function fs_ok(string $message,array $data=[]):never{fs_json(200,['ok'=>true,'message'=>$message,'data'=>$data]);}
if(!signed_in())fs_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))fs_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);
$role=(string)$_SESSION['role'];if(!in_array($role,['admin','director','sub_director','headteacher','bursar'],true))fs_json(403,['ok'=>false,'message'=>'Your role cannot manage fee structures.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)fs_json(422,['ok'=>false,'message'=>'Choose a school.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())fs_json(403,['ok'=>false,'message'=>'That school is outside your access.']);
if($_SERVER['REQUEST_METHOD']==='GET'){$q=$db->prepare('SELECT id,name FROM school_classes WHERE school_id=? ORDER BY name');$q->execute([$school]);$classes=$q->fetchAll();$q=$db->prepare("SELECT f.*,c.name class_name,(SELECT COUNT(*) FROM fee_structure_items i WHERE i.structure_id=f.id) item_count,(SELECT COUNT(*) FROM fee_assessments a WHERE a.structure_id=f.id) assessment_count FROM fee_structures f JOIN school_classes c ON c.id=f.class_id AND c.school_id=f.school_id WHERE f.school_id=? ORDER BY f.academic_year DESC,f.term,c.name,f.created_at DESC LIMIT 250");$q->execute([$school]);$structures=$q->fetchAll();$q=$db->prepare('SELECT * FROM fee_structure_items WHERE school_id=? ORDER BY structure_id,sequence_no');$q->execute([$school]);fs_ok('Fee structures loaded.',['classes'=>$classes,'structures'=>$structures,'items'=>$q->fetchAll()]);}
if($_SERVER['REQUEST_METHOD']!=='POST')fs_json(405,['ok'=>false,'message'=>'Method not allowed.']);if(!hash_equals($_SESSION['csrf']??'',(string)($_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??'')))fs_json(400,['ok'=>false,'message'=>'Your session expired. Refresh and try again.']);$action=(string)($_POST['action']??'');
try{
 if($action==='create'){$class=(int)($_POST['class_id']??0);$year=filter_var($_POST['academic_year']??null,FILTER_VALIDATE_INT);$term=trim((string)($_POST['term']??''));$title=trim((string)($_POST['title']??''));if(!$class||$year===false||$year<2000||$year>2100||$term===''||mb_strlen($term)>40||$title===''||mb_strlen($title)>180)throw new DomainException('Choose a class, academic year, term, and title.');$q=$db->prepare('SELECT 1 FROM school_classes WHERE id=? AND school_id=?');$q->execute([$class,$school]);if(!$q->fetchColumn())throw new DomainException('Choose a class in this school.');$db->beginTransaction();$q=$db->prepare('INSERT INTO fee_structures(school_id,class_id,academic_year,term,title,created_by) VALUES(?,?,?,?,?,?)');$q->execute([$school,$class,$year,$term,$title,$uid]);$id=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'create','fee_structure',$id,json_encode(['school_id'=>$school,'class_id'=>$class,'academic_year'=>$year,'term'=>$term],JSON_THROW_ON_ERROR)]);$db->commit();fs_ok('Draft fee structure created.',['id'=>$id]);}
 if($action==='add_item'){$id=(int)($_POST['structure_id']??0);$desc=trim((string)($_POST['description']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);if(!$id||$desc===''||mb_strlen($desc)>180||$amount===false||$amount<=0||$amount>100000000)throw new DomainException('Enter an item description and positive amount.');$db->beginTransaction();$q=$db->prepare("SELECT id FROM fee_structures WHERE id=? AND school_id=? AND status='draft' FOR UPDATE");$q->execute([$id,$school]);if(!$q->fetchColumn())throw new DomainException('Only a draft fee structure can be edited.');$q=$db->prepare('SELECT COALESCE(MAX(sequence_no),0)+1 FROM fee_structure_items WHERE structure_id=?');$q->execute([$id]);$seq=(int)$q->fetchColumn();$q=$db->prepare('INSERT INTO fee_structure_items(structure_id,school_id,sequence_no,description,amount) VALUES(?,?,?,?,?)');$q->execute([$id,$school,$seq,$desc,$amount]);$item=(int)$db->lastInsertId();$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'add_item','fee_structure',$id,json_encode(['school_id'=>$school,'item_id'=>$item,'description'=>$desc,'amount'=>$amount],JSON_THROW_ON_ERROR)]);$db->commit();fs_ok('Fee item added.',['structure_id'=>$id]);}
 if($action==='delete_item'){$id=(int)($_POST['structure_id']??0);$item=(int)($_POST['item_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id FROM fee_structures WHERE id=? AND school_id=? AND created_by=? AND status='draft' FOR UPDATE");$q->execute([$id,$school,$uid]);if(!$q->fetchColumn())throw new DomainException('Only your draft fee structures can be edited.');$q=$db->prepare('DELETE FROM fee_structure_items WHERE id=? AND structure_id=? AND school_id=?');$q->execute([$item,$id,$school]);if(!$q->rowCount())throw new DomainException('Fee item not found.');$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'delete_item','fee_structure',$id,json_encode(['school_id'=>$school,'item_id'=>$item],JSON_THROW_ON_ERROR)]);$db->commit();fs_ok('Fee item removed.',['structure_id'=>$id]);}
 if($action==='publish'){$id=(int)($_POST['structure_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id,status FROM fee_structures WHERE id=? AND school_id=? AND created_by=? FOR UPDATE");$q->execute([$id,$school]);$f=$q->fetch();if(!$f||$f['status']!=='draft')throw new DomainException('Only a draft fee structure can be published.');$q=$db->prepare('SELECT COUNT(*) FROM fee_structure_items WHERE structure_id=? AND school_id=?');$q->execute([$id,$school]);if(!(int)$q->fetchColumn())throw new DomainException('Add at least one fee item before publishing.');$db->prepare("UPDATE fee_structures SET status='published' WHERE id=? AND school_id=?")->execute([$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'publish','fee_structure',$id,json_encode(['school_id'=>$school],JSON_THROW_ON_ERROR)]);$db->commit();fs_ok('Fee structure published. It is ready to apply to active pupils.',['structure_id'=>$id]);}
 if($action==='archive'){$id=(int)($_POST['structure_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT id FROM fee_structures WHERE id=? AND school_id=? AND status IN ('draft','published') FOR UPDATE");$q->execute([$id,$school]);if(!$q->fetchColumn())throw new DomainException('Fee structure is not available to archive.');$db->prepare("UPDATE fee_structures SET status='archived' WHERE id=? AND school_id=?")->execute([$id,$school]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'archive','fee_structure',$id,json_encode(['school_id'=>$school],JSON_THROW_ON_ERROR)]);$db->commit();fs_ok('Fee structure archived. Existing ledger entries remain unchanged.',['structure_id'=>$id]);}
 if($action==='apply'){$id=(int)($_POST['structure_id']??0);if(!$id)throw new DomainException('Choose a fee structure.');$db->beginTransaction();$q=$db->prepare("SELECT f.*,c.name class_name FROM fee_structures f JOIN school_classes c ON c.id=f.class_id AND c.school_id=f.school_id WHERE f.id=? AND f.school_id=? FOR UPDATE");$q->execute([$id,$school]);$f=$q->fetch();if(!$f||$f['status']!=='published')throw new DomainException('Only a published fee structure can be applied.');$q=$db->prepare("SELECT p.id FROM pupils p WHERE p.school_id=? AND p.class_level=? AND p.status='active' ORDER BY p.id FOR UPDATE");$q->execute([$school,$f['class_name']]);$pupils=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));if(!$pupils)throw new DomainException('There are no active pupils in the structure’s class.');$q=$db->prepare('SELECT id,description,amount FROM fee_structure_items WHERE structure_id=? AND school_id=? ORDER BY sequence_no FOR UPDATE');$q->execute([$id,$school]);$items=$q->fetchAll();$find=$db->prepare('SELECT id FROM fee_assessments WHERE item_id=? AND pupil_id=?');$ledger=$db->prepare("INSERT INTO school_fee_ledger(school_id,pupil_id,entry_type,academic_year,term,description,amount,recorded_by) VALUES(?,?,'charge',?,?,?,?,?)");$assess=$db->prepare('INSERT INTO fee_assessments(school_id,structure_id,item_id,pupil_id,ledger_entry_id) VALUES(?,?,?,?,?)');$applied=0;foreach($pupils as $pupil){foreach($items as $item){$find->execute([$item['id'],$pupil]);if($find->fetchColumn())continue;$ledger->execute([$school,$pupil,$f['academic_year'],$f['term'],mb_substr($f['title'].' · '.$item['description'],0,180),$item['amount'],$uid]);$entry=(int)$db->lastInsertId();$assess->execute([$school,$id,$item['id'],$pupil,$entry]);$applied++;}}$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,'apply_to_class','fee_structure',$id,json_encode(['school_id'=>$school,'pupil_count'=>count($pupils),'item_count'=>count($items),'assessments_created'=>$applied],JSON_THROW_ON_ERROR)]);$db->commit();fs_ok($applied?'Fee structure applied; new charges were added to pupil ledgers.':'This fee structure was already applied. No duplicate charges were created.',['structure_id'=>$id,'pupil_count'=>count($pupils),'assessments_created'=>$applied]);}
 throw new DomainException('Choose a supported fee-structure action.');
}catch(DomainException $e){if($db->inTransaction())$db->rollBack();fs_json(422,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();error_log('Fee structures database error: '.$e->getMessage());fs_json($e->getCode()==='23000'?409:500,['ok'=>false,'message'=>'The fee structure change could not be saved. Verify the latest migration.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Fee structures request error: '.$e->getMessage());fs_json(500,['ok'=>false,'message'=>'The fee structure request could not be completed.']);}
